prompts.user:
/ [셋업] POS별 문항 풀에서 랜덤 인덱스(*_IDX) 추출
@SET(N_IDX, "@INDEX("@N_SEN@", "@N_SEN[.]@")@", SELF)@
@SET(V_IDX, "@INDEX("@V_SEN@", "@V_SEN[.]@")@", SELF)@
@SET(ADJ_IDX, "@INDEX("@ADJ_SEN@", "@ADJ_SEN[.]@")@", SELF)@
@SET(OTH_IDX, "@INDEX("@OTH_SEN@", "@OTH_SEN[.]@")@", SELF)@

// [셋업] 추출한 문항·정답(·보기)을 JSON_test_config에 기록
@UPJ(JSON_test_config.Noun[@R_i@].problem, "@EVAL(@R_i@)@. 아래 문장 속 <b>@N_POLY[@N_IDX@]@</b>의 의미를 우리말로 쓰시오<br>@N_SEN[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].answer, "@N_ANS[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].polysemy, "@N_POLY[@N_IDX@]@")@

@UPJ(JSON_test_config.Verb[@R_i@].problem, "@EVAL(@R_i@)@. 아래 문장 속 <b>@V_POLY[@V_IDX@]@</b>의 의미를 우리말로 쓰시오<br>@V_SEN[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].answer, "@V_ANS[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].polysemy, "@V_POLY[@V_IDX@]@")@

@UPJ(JSON_test_config.Adjective[@R_i@].problem, "@EVAL(@R_i@)@. 아래 문장 속 <b>@ADJ_POLY[@ADJ_IDX@]@</b>의 의미를 우리말로 쓰시오<br>@ADJ_SEN[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].answer, "@ADJ_ANS[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].polysemy, "@ADJ_POLY[@ADJ_IDX@]@")@

@UPJ(JSON_test_config.others[@R_i@].problem, "@EVAL(@R_i@)@. 아래 문장 속 <b>@OTH_POLY[@OTH_IDX@]@</b>의 의미를 우리말로 쓰시오<br>@OTH_SEN[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].answer, "@OTH_ANS[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].polysemy, "@OTH_POLY[@OTH_IDX@]@")@

// [채점] 명사 학생 응답 정오 판정 후 점수·correctness 기록 (LLM 판정 결과(1/0) 사용)

1. Noun
T/F boolean: @TR@TN(-1)@[@R_i@]@

Current Score: @JSON_test_config.Result[1].Noun@

Enumerated: @EVAL("@JSON_test_config.Result[1].Noun@ + @TR@TN(-1)@[@R_i@]@")@

update:
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ + @TR@TN(-1)@[@R_i@]@")@)@
@UPJ(JSON_test_config.Noun[@R_i@].Student_answer, "@TEXT(P_N@R_i@)@")@
@UPJ(JSON_test_config.Noun[@R_i@].correctness, @TR@TN(-1)@[@R_i@]@)@

// [채점] 동사 학생 응답 정오 판정 후 점수·correctness 기록 (LLM 판정 결과(1/0) 사용)

2. Verb
T/F boolean: @TR@TN(-1)@[@R_i@]@

Current Score: @JSON_test_config.Result[1].Verb@

Enumerated: @EVAL("@JSON_test_config.Result[1].Verb@ + @TR@TN(-1)@[@R_i@]@")@

update:
@UPJ(JSON_test_config.Result[1].Verb, @EVAL("@JSON_test_config.Result[1].Verb@ + @TR@TN(-1)@[@R_i@]@")@)@
@UPJ(JSON_test_config.Verb[@R_i@].Student_answer, "@TEXT(P_V@R_i@)@")@
@UPJ(JSON_test_config.Verb[@R_i@].correctness, @TR@TN(-1)@[@R_i@]@)@

// [채점] 형용사 학생 응답 정오 판정 후 점수·correctness 기록 (LLM 판정 결과(1/0) 사용)

3. Adjective
T/F boolean: @TR@TN(-1)@[@R_i@]@

Current Score: @JSON_test_config.Result[1].Adjective@

Enumerated: @EVAL("@JSON_test_config.Result[1].Adjective@ + @TR@TN(-1)@[@R_i@]@")@

update:
@UPJ(JSON_test_config.Result[1].Adjective, @EVAL("@JSON_test_config.Result[1].Adjective@ + @TR@TN(-1)@[@R_i@]@")@)@
@UPJ(JSON_test_config.Adjective[@R_i@].Student_answer, "@TEXT(P_ADJ@R_i@)@")@
@UPJ(JSON_test_config.Adjective[@R_i@].correctness, @TR@TN(-1)@[@R_i@]@)@

// [채점] 기타 학생 응답 정오 판정 후 점수·correctness 기록 (LLM 판정 결과(1/0) 사용)

4. Others
T/F boolean: @TR@TN(-1)@[@R_i@]@

Current Score: @JSON_test_config.Result[1].others@

Enumerated: @EVAL("@JSON_test_config.Result[1].others@ + @TR@TN(-1)@[@R_i@]@")@

update:
@UPJ(JSON_test_config.Result[1].others, @EVAL("@JSON_test_config.Result[1].others@ + @TR@TN(-1)@[@R_i@]@")@)@
@UPJ(JSON_test_config.others[@R_i@].Student_answer, "@TEXT(P_OTH@R_i@)@")@
@UPJ(JSON_test_config.others[@R_i@].correctness, @TR@TN(-1)@[@R_i@]@)@

// [집계] 인덱싱 보정(-1) 후 POS 점수 누적 합산(Cumulative)
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ - 1")@)@
@UPJ(JSON_test_config.Result[1].Verb, @EVAL("@JSON_test_config.Result[1].Verb@ - 1")@)@
@UPJ(JSON_test_config.Result[1].Adjective, @EVAL("@JSON_test_config.Result[1].Adjective@ - 1")@)@
@UPJ(JSON_test_config.Result[1].others, @EVAL("@JSON_test_config.Result[1].others@ - 1")@)@

@UPJ(JSON_test_config.Result[1].Cumulative, @EVAL("@JSON_test_config.Result[1].Noun@+@JSON_test_config.Result[1].Verb@+@JSON_test_config.Result[1].Adjective@+@JSON_test_config.Result[1].others@")@)@

/ [초기화] 다음 응시를 위한 점수·결과 초기화
@UPJ(JSON_test_config.Result[1].Noun, 1)@
@UPJ(JSON_test_config.Result[1].Verb, 1)@
@UPJ(JSON_test_config.Result[1].Adjective, 1)@
@UPJ(JSON_test_config.Result[1].others, 1)@
@UPJ(JSON_test_config.Result[1].Cumulative, 1)@
